"Потом произошло: Алия ухаживала за птенцом": "Dann geschah Folgendes: Alija kümmerte sich um das Vogeljunge",
"Что произошло потом?": "Was geschah danach?",
"Что произошло потом? Утром Алия нашла в саду птенца. Она осторожно положила его в коробку и напоила водой. Через два дня птенец окреп и улетел.": "Was geschah danach? Am Morgen fand Alija im Garten ein Vogeljunges. Sie legte es vorsichtig in eine Schachtel und gab ihm Wasser. Zwei Tage später war das Vogeljunge kräftig und flog davon.",
"Потом произошло: Бека заблудился в лесу": "Dann geschah Folgendes: Beka verirrte sich im Wald",
"Что произошло потом? Бека пошёл за грибами. В лесу он заблудился. Тогда он вспомнил совет отца, пошёл по тропинке и скоро вышел к дому.": "Was geschah danach? Beka ging Pilze sammeln. Er verirrte sich im Wald. Dann erinnerte er sich an den Rat seines Vaters, folgte einem Pfad und kam bald am Haus heraus.",
"Потом произошло: Дети принесли доски и молотки": "Dann geschah Folgendes: Die Kinder brachten Bretter und Hämmer",
"Что произошло потом? Дети решили построить скворечник. Они принесли доски и молотки. Весной в скворечнике поселилась птичья семья.": "Was geschah danach? Die Kinder beschlossen, ein Vogelhäuschen zu bauen. Sie brachten Bretter und Hämmer. Im Frühling ließ sich eine Vogelfamilie im Vogelhäuschen nieder.",
